// lib/library/feed-parse.ts
//
// Reading a podcast or book feed without an XML library.
//
// Pure and unit-tested. Tolerant on purpose: podcast feeds are generated by
// hundreds of different tools and a strict parser rejects a large fraction of
// the real web. What this does NOT do is evaluate anything — it extracts text
// and URLs, and every URL is filtered to http(s) before it can be stored.
//
// The shapes that actually turn up in the wild, all handled here:
//   • RSS 2.0 and Atom, which name everything differently
//   • CDATA sections wrapping titles and descriptions
//   • HTML entities inside those titles
//   • <enclosure> attributes in any order, single or double quoted
//   • iTunes durations as "3600", "45:11" or "1:02:03"
//   • namespaced tags (itunes:duration, media:content) on any prefix

export type ParsedFeedItem = {
  guid: string;
  title: string;
  description: string;
  mediaUrl: string | null;
  pageUrl: string | null;
  imageUrl: string | null;
  durationSeconds: number | null;
  publishedAt: string | null;
};

export type ParsedFeed = {
  title: string;
  description: string;
  author: string | null;
  imageUrl: string | null;
  items: ParsedFeedItem[];
};

/** A feed with more entries than this is truncated; nobody scrolls 500 episodes. */
export const MAX_FEED_ITEMS = 300;

const ENTITIES: Record<string, string> = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
};

/** Decode the entities a feed actually uses, including numeric ones. */
export function decodeEntities(text: string): string {
  return text.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, name: string) => {
    const key = name.toLowerCase();
    if (key.startsWith('#x')) {
      const code = Number.parseInt(key.slice(2), 16);
      return Number.isFinite(code) && code > 0 ? String.fromCodePoint(code) : match;
    }
    if (key.startsWith('#')) {
      const code = Number.parseInt(key.slice(1), 10);
      return Number.isFinite(code) && code > 0 ? String.fromCodePoint(code) : match;
    }
    return ENTITIES[key] ?? match;
  });
}

/** Text content of an element: CDATA unwrapped, tags stripped, entities decoded. */
export function textContent(raw: string | null | undefined): string {
  if (!raw) return '';
  const withoutCdata = raw.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1');
  return decodeEntities(withoutCdata.replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();
}

/** First match of a tag, on any namespace prefix. */
function tagContent(xml: string, tag: string): string | null {
  const pattern = new RegExp(`<(?:[a-z0-9-]+:)?${tag}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/(?:[a-z0-9-]+:)?${tag}>`, 'i');
  return pattern.exec(xml)?.[1] ?? null;
}

/** An attribute from a tag, quoted either way. */
function attr(tag: string, name: string): string | null {
  const pattern = new RegExp(`${name}\\s*=\\s*("([^"]*)"|'([^']*)')`, 'i');
  const match = pattern.exec(tag);
  const value = match?.[2] ?? match?.[3];
  return value ? decodeEntities(value).trim() : null;
}

/**
 * iTunes durations, in all three forms the spec allows and publishers use.
 * Returns null rather than 0 for junk: 0 reads as "instant" in a player.
 */
export function parseDuration(raw: string | null | undefined): number | null {
  const text = (raw ?? '').trim();
  if (!text) return null;
  if (/^\d+$/.test(text)) {
    const seconds = Number(text);
    return seconds > 0 ? seconds : null;
  }
  const parts = text.split(':');
  if (parts.length < 2 || parts.length > 3 || parts.some((part) => !/^\d+$/.test(part.trim()))) return null;
  const numbers = parts.map((part) => Number(part.trim()));
  const seconds = numbers.length === 3
    ? numbers[0] * 3600 + numbers[1] * 60 + numbers[2]
    : numbers[0] * 60 + numbers[1];
  return seconds > 0 ? seconds : null;
}

/** A publication date as an ISO string, or null when it is unusable. */
export function parseFeedDate(raw: string | null | undefined, now: Date = new Date()): string | null {
  const text = (raw ?? '').trim();
  if (!text) return null;
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) return null;
  // A feed dated in the year 3000 sorts above everything forever. Publishers
  // do get this wrong, and one bad row would pin itself to the top of the list.
  const year = parsed.getUTCFullYear();
  if (year < 1990 || year > now.getUTCFullYear() + 2) return null;
  return parsed.toISOString();
}

/** Only http(s). A feed offering javascript: or data: is offering an attack. */
export function safeFeedUrl(raw: string | null | undefined): string | null {
  const text = (raw ?? '').trim();
  if (!text) return null;
  try {
    const url = new URL(text);
    return url.protocol === 'https:' || url.protocol === 'http:' ? url.href : null;
  } catch {
    return null;
  }
}

function itemBlocks(xml: string): string[] {
  const rss = [...xml.matchAll(/<item(?:\s[^>]*)?>([\s\S]*?)<\/item>/gi)].map((m) => m[1]);
  if (rss.length) return rss;
  return [...xml.matchAll(/<entry(?:\s[^>]*)?>([\s\S]*?)<\/entry>/gi)].map((m) => m[1]);
}

/** The playable file, from wherever this generator decided to put it. */
function mediaUrlFor(block: string): string | null {
  const enclosure = /<enclosure(?:\s[^>]*)?\/?>/i.exec(block)?.[0];
  const fromEnclosure = enclosure ? safeFeedUrl(attr(enclosure, 'url')) : null;
  if (fromEnclosure) return fromEnclosure;

  const media = /<(?:[a-z0-9-]+:)?content(?:\s[^>]*)?\/?>/i.exec(block)?.[0];
  const fromMedia = media ? safeFeedUrl(attr(media, 'url')) : null;
  if (fromMedia) return fromMedia;

  // Atom puts it on a link with rel="enclosure".
  for (const link of block.matchAll(/<link(?:\s[^>]*)?\/?>/gi)) {
    if ((attr(link[0], 'rel') ?? '').toLowerCase() === 'enclosure') {
      const href = safeFeedUrl(attr(link[0], 'href'));
      if (href) return href;
    }
  }
  return null;
}

/** The page to open, which is not the audio file. */
function pageUrlFor(block: string): string | null {
  const fromInline = safeFeedUrl(textContent(tagContent(block, 'link')));
  if (fromInline) return fromInline;
  for (const link of block.matchAll(/<link(?:\s[^>]*)?\/?>/gi)) {
    const rel = (attr(link[0], 'rel') ?? 'alternate').toLowerCase();
    if (rel === 'alternate') {
      const href = safeFeedUrl(attr(link[0], 'href'));
      if (href) return href;
    }
  }
  return null;
}

function imageUrlFor(block: string): string | null {
  const image = /<(?:[a-z0-9-]+:)?image(?:\s[^>]*)?\/?>/i.exec(block)?.[0];
  const fromAttr = image ? safeFeedUrl(attr(image, 'href') ?? attr(image, 'url')) : null;
  if (fromAttr) return fromAttr;
  return safeFeedUrl(textContent(tagContent(block, 'url')));
}

export function parseFeed(xml: string, now: Date = new Date()): ParsedFeed | null {
  if (!xml || !xml.trimStart().startsWith('<')) return null;
  // Split the channel header off the items so a channel-level <title> is not
  // read from the first episode, and vice versa.
  const firstItem = xml.search(/<(?:item|entry)(?:\s|>)/i);
  const header = firstItem > 0 ? xml.slice(0, firstItem) : xml;

  const title = textContent(tagContent(header, 'title'));
  const blocks = itemBlocks(xml).slice(0, MAX_FEED_ITEMS);
  // A document with neither a title nor a single entry is not a feed we can use.
  if (!title && blocks.length === 0) return null;

  const items: ParsedFeedItem[] = blocks.map((block, index) => {
    const itemTitle = textContent(tagContent(block, 'title'));
    const mediaUrl = mediaUrlFor(block);
    const guid = textContent(tagContent(block, 'guid')) || textContent(tagContent(block, 'id'))
      || mediaUrl || `${itemTitle}#${index}`;
    return {
      guid: guid.slice(0, 400),
      title: itemTitle.slice(0, 300) || 'Untitled',
      description: (textContent(tagContent(block, 'description'))
        || textContent(tagContent(block, 'summary'))
        || textContent(tagContent(block, 'content'))).slice(0, 2000),
      mediaUrl,
      pageUrl: pageUrlFor(block),
      imageUrl: imageUrlFor(block),
      durationSeconds: parseDuration(textContent(tagContent(block, 'duration'))),
      publishedAt: parseFeedDate(
        textContent(tagContent(block, 'pubDate'))
        || textContent(tagContent(block, 'published'))
        || textContent(tagContent(block, 'updated')),
        now,
      ),
    };
  });

  return {
    title: (title || 'Untitled feed').slice(0, 300),
    description: (textContent(tagContent(header, 'description')) || textContent(tagContent(header, 'subtitle'))).slice(0, 2000),
    author: textContent(tagContent(header, 'author')) || null,
    imageUrl: imageUrlFor(header),
    items,
  };
}

/** How far through something is, as a percentage a progress bar can use. */
export function progressPercent(positionSeconds: number, durationSeconds: number | null): number {
  if (!durationSeconds || durationSeconds <= 0) return 0;
  return Math.max(0, Math.min(100, Math.round((positionSeconds / durationSeconds) * 100)));
}

/** "45 min", "1 hr 2 min" — the way a listener thinks about length. */
export function formatDuration(seconds: number | null): string {
  if (!seconds || seconds <= 0) return '';
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.round((seconds % 3600) / 60);
  if (hours === 0) return `${Math.max(1, minutes)} min`;
  if (minutes === 0) return `${hours} hr`;
  return `${hours} hr ${minutes} min`;
}
